const upsertWikiPage = `-- name: UpsertWikiPage :one
INSERT INTO wiki_page (space_id, path, title, page_type, content, frontmatter, backlinks, content_hash, current_revision_id)
VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9)
ON CONFLICT (space_id, path)
DO UPDATE SET
    title = EXCLUDED.title,
    page_type = EXCLUDED.page_type,
    content = EXCLUDED.content,
    frontmatter = EXCLUDED.frontmatter,
    backlinks = EXCLUDED.backlinks,
    content_hash = EXCLUDED.content_hash,
    current_revision_id = COALESCE(EXCLUDED.current_revision_id, wiki_page.current_revision_id),
    updated_at = now()
RETURNING id, space_id, path, title, page_type, content, frontmatter, backlinks, content_hash, current_revision_id, created_at, updated_at
`

type UpsertWikiPageParams struct {
	SpaceID     pgtype.UUID `json:"space_id"`
	Path        string      `json:"path"`
	Title       pgtype.Text `json:"title"`
	PageType    pgtype.Text `json:"page_type"`
	Content     string      `json:"content"`
	Frontmatter []byte      `json:"frontmatter"`
	Backlinks   []byte      `json:"backlinks"`
	ContentHash string      `json:"content_hash"`
	RevisionID  pgtype.UUID `json:"revision_id"`
}

func (q *Queries) UpsertWikiPage(ctx context.Context, arg UpsertWikiPageParams) (WikiPage, error) {
	row := q.db.QueryRow(ctx, upsertWikiPage,
		arg.SpaceID,
		arg.Path,
		arg.Title,
		arg.PageType,
		arg.Content,
		arg.Frontmatter,
		arg.Backlinks,
		arg.ContentHash,
		arg.RevisionID,
	)
	var i WikiPage
	err := row.Scan(
		&i.ID,
		&i.SpaceID,
		&i.Path,
		&i.Title,
		&i.PageType,
		&i.Content,
		&i.Frontmatter,
		&i.Backlinks,
		&i.ContentHash,
		&i.CurrentRevisionID,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
